#!/usr/bin/env bash
# A2 Connect: обновление сайта, PWA кабинета и файлов приложений. Запуск на Москве от root.
set -e
echo '>> Лендинг'
mkdir -p /var/www/a2/download /var/www/a2-pwa
echo '' | base64 -d | tar xz -C /var/www/a2
echo '>> PWA'
echo '' | base64 -d | tar xz -C /var/www/a2-pwa
install -m 755 /var/www/a2-pwa/sync.sh /usr/local/bin/a2-pwa-sync
rm -f /var/www/a2-pwa/sync.sh
/usr/local/bin/a2-pwa-sync || echo '!! не смог получить страницу кабинета (PWA пропущено)'
echo '*/10 * * * * root /usr/local/bin/a2-pwa-sync >/dev/null 2>&1' > /etc/cron.d/a2-pwa

echo '>> Файлы приложений с GitHub'
REL=https://github.com/areshetov89/a2-connect-app/releases/latest/download
for f in A2Connect.apk A2Connect-armv7.apk A2Connect-Setup.exe A2Connect-Mac-AppleSilicon.dmg A2Connect-Mac-Intel.dmg; do
  if curl -fsSL --max-time 300 -o /tmp/$f.part "$REL/$f"; then mv /tmp/$f.part /var/www/a2/download/$f; echo "   ok  $f"; else rm -f /tmp/$f.part; echo "   --  $f (пока нет)"; fi
done
D=/var/www/a2/download; [ ! -f $D/A2Connect-Mac-AppleSilicon.dmg ] && [ -f $D/A2Connect-Mac-Intel.dmg ] && cp $D/A2Connect-Mac-Intel.dmg $D/A2Connect-Mac-AppleSilicon.dmg && echo '   Mac M1–M4: пока версия Intel (работает через Rosetta)'
chmod 644 /var/www/a2/download/* 2>/dev/null || true

echo '>> Caddy'
cp /etc/caddy/Caddyfile /etc/caddy/Caddyfile.bak
python3 - <<'PY'
import re
p='/etc/caddy/Caddyfile'; s=open(p).read()
lk='''lk.a2-connect.com {
	handle /a2-sw.js {
		root * /var/www/a2-pwa
		header Cache-Control "no-cache"
		file_server
	}
	handle /a2-pwa/* {
		root * /var/www
		file_server
	}
	handle /apple-touch-icon* {
		root * /var/www/a2-pwa
		rewrite * /icon-180.png
		file_server
	}
	@page {
		not path /api/* /assets/*
		header Accept *text/html*
		file {
			root /var/www/a2-pwa
			try_files /index.html
		}
	}
	handle @page {
		root * /var/www/a2-pwa
		rewrite * /index.html
		header Cache-Control "no-cache"
		file_server
	}
	handle {
		reverse_proxy https://31.76.59.45 {
			header_up Host lk.a2-connect.com
			header_up X-Real-IP {remote_host}
			transport http {
				tls_server_name lk.a2-connect.com
			}
		}
	}
}
'''
land='''a2-connect.com, www.a2-connect.com {
	redir /download/* https://github.com/areshetov89/a2-connect-app/releases/latest{path} 302
	root * /var/www/a2
	encode gzip
	header /index.html Cache-Control "no-cache"
	header / Cache-Control "no-cache"
	file_server
}
'''
def put(s, head, block):
    rx=re.compile(r'^'+re.escape(head)+r' \{\n.*?^\}\n', re.S|re.M)
    s=rx.sub('', s)
    return s.rstrip('\n')+'\n\n'+block
s=put(s,'lk.a2-connect.com',lk)
s=put(s,'a2-connect.com, www.a2-connect.com',land)
open(p,'w').write(s)
PY
if caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile 2>&1 | tail -2; [ ${PIPESTATUS[0]} -eq 0 ]; then
  systemctl reload caddy; sleep 2
else
  cp /etc/caddy/Caddyfile.bak /etc/caddy/Caddyfile; echo '!! ОШИБКА в конфиге Caddy, конфиг откатил'; exit 1
fi

echo '>> Проверка'
c() { curl -s --max-time 10 --resolve "$1:443:127.0.0.1" -H 'Accept: text/html' "https://$1$2"; }
c a2-connect.com / | grep -q 'Скачать приложение</h2>' && echo '   лендинг: ок' || echo '   лендинг: НЕ обновился'
c lk.a2-connect.com / | grep -q 'a2-pwa/manifest' && echo '   PWA: ок' || echo '   PWA: нет'
ls -la /var/www/a2/download
echo 'ГОТОВО'
